from collections import deque

def group_states(grid, start, goal):
    # Define movements
    movements = [(0, 1), (0, -1), (1, 0), (-1, 0)]

    # Initialize queue with starting state
    queue = deque([(start, [start])])

    # Initialize sets to store visited states and grouped states
    visited = set()
    groups = {}

    while queue:
        state, path = queue.popleft()

        if state not in visited:
            visited.add(state)

            for movement in movements:
                x, y = (state // len(grid[0])) + movement[0], (state % len(grid[0])) + movement[1]

                # Check if within grid boundaries and not blocked
                if 0 <= x < len(grid) and 0 <= y < len(grid[0]) and grid[x][y] != 'X':
                    new_state = x * len(grid[0]) + y

                    # If goal is reached, mark as group with path
                    if new_state == goal:
                        groups[new_state] = path + [new_state]

                    # Otherwise, add to queue
                    else:
                        queue.append((new_state, path + [new_state]))

    return list(groups.values())
